#include "Plugin.cpp"
#include <iostream>
#include "ResizeChecks.h"
int main(){ScopedJuceInitialiser_GUI gui;Processor p;p.prepareToPlay(48000,256);MidiBuffer m;AudioBuffer<float>b(2,256);b.clear();p.fire=1;p.processBlock(b,m);for(int c=0;c<2;++c)for(int i=0;i<256;++i)if(b.getSample(c,i)!=(i==0?0.25f:0.0f))return 1;b.clear();p.processBlock(b,m);if(b.getMagnitude(0,256)!=0)return 2;p.signal=1;p.tone=1000;p.processBlock(b,m);for(int i=0;i<256;++i)if(std::abs(b.getSample(0,i)-0.125*std::sin(MathConstants<double>::twoPi*1000*i/48000))>0.000001)return 3;p.signal=2;int time=0;
for(int profile:{0,1,2})for(int block:{64,511,1024}){p.quality=profile;p.prepareToPlay(48000,block);p.signal=2;time=0;for(int j=0;j<300;++j){AudioBuffer<float>live(2,block);live.clear();p.processBlock(live,m);for(int c=0;c<2;++c)for(int i=0;i<block;++i)if(live.getSample(c,i)!=TestSignal::get(profile).samples[(size_t)((time+i)%TestSignal::get(profile).size)])return 4;time+=block;}}
MemoryBlock saved;p.getStateInformation(saved);Processor restored;restored.setStateInformation(saved.getData(),(int)saved.getSize());restored.prepareToPlay(48000,256);AudioBuffer<float> resumed(2,256);resumed.clear();restored.processBlock(resumed,m);if(restored.signal.load()!=2 || resumed.getSample(0,0)!=TestSignal::get(restored.quality.load()).samples[0])return 6;
std::unique_ptr<AudioProcessorEditor> editor(p.createEditor());if(!ResizeChecks::run(*static_cast<Editor*>(editor.get()),"Probe"))return 5;auto image=editor->createComponentSnapshot(editor->getLocalBounds());FileOutputStream output(File::getCurrentWorkingDirectory().getChildFile("NF-Capture-Probe-R4.png"));output.setPosition(0);output.truncate();PNGImageFormat png;png.writeImageToStream(image,output);
std::cout<<"PASS: impulse amplitude, single-shot output and sine frequency/amplitude; periodic isolated impulses across 3 profiles and 3 block sizes; resizing and logo reset and LIVE restoration pass.\n";}
